   225|  videoUnderstandings: VideoUnderstanding[];
   226|}): Promise<PublicChatAnswerResult> {
   227|  const endpoint = getGatewayModelEndpoint();
   228|  if (!isPublicChatAIConfigured() || !endpoint) {
   229|    throw new Error('IVX AI proxy configuration is missing.');
   230|  }
   231|
   232|  const promptParts = [
   233|    'Recent public chat transcript:',
   234|    buildTranscript(input.history),
   235|    '',
   236|  ];
   237|  if (input.businessContext) {
   238|    promptParts.push(input.businessContext, '');
   239|  }
   240|  if (input.images.length > 0) {
   241|    promptParts.push(
   242|      `Note: ${input.images.length} image attachment(s) accompany this message — analyze them as part of your answer.`,
   243|      '',
   244|    );
   245|  }
   246|  if (input.documents.length > 0) {
   247|    promptParts.push(
   248|      `Note: ${input.documents.length} deal-room document(s) accompany this message: ${input.documents
   249|        .map((doc) => `${doc.name ?? doc.url} [${doc.kind}] ${doc.url}`)
   250|        .join('; ')}. Analyze them as an acquisition analyst per the instructions above.`,
   251|      '',
   252|    );
   253|  }
   254|  const extractedContentBlock = buildExtractedDocumentContentBlock(input.extractedDocuments);
   255|  if (extractedContentBlock) {
   256|    promptParts.push(extractedContentBlock, '');
   257|  }
   258|  const videoContentBlock = buildVideoUnderstandingBlock(input.videoUnderstandings);
   259|  if (videoContentBlock) {
   260|    promptParts.push(videoContentBlock, '');
   261|  }
   262|  promptParts.push(
   263|    `User message: ${input.message || (input.images.length > 0 ? 'Analyze the attached image(s).' : '')}`,
   264|    '',
   265|    'Reply directly to the user message. If the user asks for an exact token or proof string, include it exactly.',
   266|  );
   267|
   268|  const result = await requestIVXAIText({
   269|    module: 'public-chat',
   270|    requestId: input.sessionId,
   271|    model: getPublicChatModel(),
   272|    system: buildSystemPrompt(
   273|      input.sessionId,
   274|      input.images.length > 0,
   275|      input.documents,
   276|      extractedContentBlock,
   277|      videoContentBlock,
   278|    ),
   279|    prompt: promptParts.join('\n'),
   280|    images: input.images.length > 0 ? input.images : undefined,
   281|  });
