   362|    hasImageAttachments: images.length > 0,
   363|  });
   364|  console.log('[PublicChatAI] Authoritative intent router:', {
   365|    sessionId: input.sessionId,
   366|    traceId: authoritativeDecision.traceId,
   367|    intent: authoritativeDecision.intent,
   368|    confidence: authoritativeDecision.confidence,
   369|    route: authoritativeDecision.selectedRoute,
   370|    reason: authoritativeDecision.reason,
   371|    publicBoundary: authoritativeDecision.safetyStage.publicBoundary,
   372|  });
   373|
   374|  // Public chat: block execution, deployment, destructive actions, owner controls
   375|  if (authoritativeDecision.selectedRoute === 'CLARIFICATION' && authoritativeDecision.safetyStage.publicBoundary === 'public_blocked') {
   376|    return {
   377|      answer: `This request requires owner authentication. Safe technical questions, code reviews, architecture designs, and product information are available without login. Try rephrasing your question if you want an explanation rather than an execution.`,
   378|      model: 'ivx-authoritative-router',
