   154|function detectDefinitionQuestion(compact: string): boolean {
   155|  if (/^(what is|what are|what does|define|explain)\b/.test(compact) && compact.length < 150) return true;
   156|  return false;
   157|}
   158|
   159|/**
   160| * Answer a definition question about real estate / IVX terms.
   161| */
   162|function answerDefinitionQuestion(message: string): string | null {
   163|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
   164|  const definitions: Array<{ terms: string[]; answer: string }> = [
   165|    { terms: ['reit'], answer: 'A REIT (Real Estate Investment Trust) is a company that owns, operates, or finances income-generating real estate. Investors buy shares and receive dividends, but do not directly own the properties.' },
   166|    { terms: ['dst'], answer: 'A DST (Delaware Statutory Trust) is a legal entity used for 1031 exchanges, allowing investors to exchange one property for fractional interests in multiple properties without immediate capital gains tax.' },
   167|    { terms: ['jv', 'joint venture'], answer: 'A JV (Joint Venture) is a business arrangement where two or more parties pool resources for a specific project. In real estate, JVs combine capital, expertise, and property ownership.' },
   168|    { terms: ['1031'], answer: 'A 1031 exchange is a tax-deferred swap of investment properties under IRC Section 1031, allowing investors to defer capital gains taxes when reinvesting proceeds into a like-kind property.' },
   169|    { terms: ['fractional', 'fractional ownership'], answer: 'Fractional ownership allows multiple investors to share ownership of a single asset, each holding a percentage. It reduces the minimum investment and diversifies risk.' },
   170|    { terms: ['tokeniz', 'tokenization'], answer: 'Tokenization is the process of representing ownership rights as digital tokens on a blockchain, enabling fractional ownership and easier transfer of real estate interests.' },
   171|    { terms: ['cap rate', 'capitalization rate'], answer: 'Cap rate (capitalization rate) is the ratio of net operating income to property value, expressed as a percentage. It measures the potential return on a real estate investment.' },
   172|    { terms: ['roi', 'return on investment'], answer: 'ROI (Return on Investment) measures the profitability of an investment relative to its cost, expressed as a percentage. In real estate, it includes rental income plus appreciation.' },
   173|    { terms: ['irr', 'internal rate of return'], answer: 'IRR (Internal Rate of Return) is the annualized rate of return that makes the net present value of all cash flows equal zero. It accounts for the time value of money in real estate projections.' },
   174|    { terms: ['waterfall', 'waterfall distribution'], answer: 'A waterfall distribution is a tiered allocation of profits in a real estate JV. Returns are distributed in priority order: capital returned first, then preferred return, then sponsor promote, then remaining split.' },
   175|    { terms: ['preferred return', 'pref'], answer: 'A preferred return (pref) is a minimum return percentage promised to investors before the sponsor receives their promote. Common in real estate JVs, typically 6-10% annually.' },
   176|    { terms: ['promote', 'sponsor promote'], answer: 'Sponsor promote is the performance fee earned by the JV sponsor for exceeding the preferred return. It aligns sponsor and investor incentives — the sponsor earns more when returns are higher.' },
   177|    { terms: ['k1', 'schedule k-1'], answer: 'A Schedule K-1 is a tax form reporting each partner\'s share of income, losses, deductions, and credits from a partnership. Real estate JV investors receive K-1s annually for tax filing.' },
   178|    { terms: ['accredited investor'], answer: 'An accredited investor is an individual with net worth over $1M (excluding primary residence) or annual income over $200K ($300K joint). Many private real estate offerings require accredited investor status.' },
   179|  ];
   180|  for (const def of definitions) {
   181|    if (def.terms.some((t) => text.includes(t))) return def.answer;
   182|  }
   183|  return null;
   184|}
   185|
   186|/**
   187| * Evaluate a math expression from natural language.
   188| */
   189|function evaluateMathQuestion(message: string): number | null {
   190|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s+\-*/=.]/g, ' ').replace(/\s+/g, ' ').trim();
   191|  // square root
   192|  const sqrtMatch = text.match(/(?:square root|sqrt)\s+of\s+(\d+(?:\.\d+)?)/);
   193|  if (sqrtMatch) {
   194|    const n = parseFloat(sqrtMatch[1]);
   195|    return Math.sqrt(n);
   196|  }
   197|  // word-form
   198|  const wordMatch = text.match(/(\d+(?:\.\d+)?)\s+(plus|minus|multiplied by|times|divided by|added to|subtracted from)\s+(\d+(?:\.\d+)?)/);
   199|  if (wordMatch) {
   200|    const a = parseFloat(wordMatch[1]);
   201|    const op = wordMatch[2];
   202|    const b = parseFloat(wordMatch[3]);
   203|    switch (op) {
   204|      case 'plus': case 'added to': return a + b;
   205|      case 'minus': case 'subtracted from': return op === 'subtracted from' ? b - a : a - b;
   206|      case 'multiplied by': case 'times': return a * b;
   207|      case 'divided by': return b === 0 ? null : a / b;
   208|    }
   209|  }
   210|  // symbol-form: "what is 15 x 3" / "15 * 3" / "10 + 5"
   211|  const symMatch = text.match(/(\d+(?:\.\d+)?)\s*([+\-*/x])\s*(\d+(?:\.\d+)?)/);
   212|  if (symMatch) {
   213|    const a = parseFloat(symMatch[1]);
   214|    const op = symMatch[2];
   215|    const b = parseFloat(symMatch[3]);
   216|    switch (op) {
   217|      case '+': return a + b;
   218|      case '-': return a - b;
   219|      case '*': case 'x': return a * b;
   220|      case '/': return b === 0 ? null : a / b;
   221|    }
   222|  }
   223|  return null;
   224|}
   225|
   226|/**
   227| * Build the direct answer for a general conversation question.
   228| */
   229|export function buildIVXConversationAnswer(message: string): string | null {
