  1213|// ─── Clarification Question Builder (Item 8) ──────────────────────────
  1214|
  1215|export function buildClarificationQuestion(originalMessage: string): string {
  1216|  const text = normalize(originalMessage);
  1217|  // Check if it seems like a knowledge question or execution request
  1218|  const hasExecutionWords = /\b(?:fix|patch|deploy|commit|push|build|implement|create)\b/i.test(text);
  1219|  const hasKnowledgeWords = /\b(?:explain|what|why|how|review|design|architecture|compare)\b/i.test(text);
  1220|
  1221|  if (hasExecutionWords && hasKnowledgeWords) {
  1222|    return 'Do you want an explanation only, or do you want IVX IA to change the code and deploy it?';
  1223|  }
  1224|  if (hasExecutionWords) {
  1225|    return 'Do you want me to execute this change (fix, deploy, commit), or just explain how to do it?';
  1226|  }
  1227|  return 'Could you clarify what you are asking for — an explanation, a code review, a design, or an execution task?';
  1228|}
  1229|
  1230|// ─── Truthful Response States (Item 10) ───────────────────────────────
  1231|
  1232|export type IVXResponseState =
  1233|  | 'THINKING'
  1234|  | 'ANSWERING'
  1235|  | 'WAITING_FOR_CLARIFICATION'
  1236|  | 'WAITING_FOR_OWNER_APPROVAL'
  1237|  | 'EXECUTING'
  1238|  | 'TESTING'
  1239|  | 'COMMITTING'
  1240|  | 'DEPLOYING'
  1241|  | 'VERIFYING'
  1242|  | 'COMPLETED'
  1243|  | 'FAILED'
  1244|  | 'BLOCKED';
  1245|
  1246|export function stateForIntent(decision: IVXIntentDecision): IVXResponseState {
  1247|  switch (decision.selectedRoute) {
  1248|    case 'LLM_TEXT_RESPONSE':
  1249|    case 'PUBLIC_LLM_RESPONSE':
  1250|    case 'MANUAL_LLM_RESPONSE':
  1251|      return 'ANSWERING';
  1252|    case 'DEVELOPER_WORKER':
  1253|      return decision.destructiveAction ? 'WAITING_FOR_OWNER_APPROVAL' : 'EXECUTING';
  1254|    case 'DEPLOYMENT_ACTION':
  1255|      return 'WAITING_FOR_OWNER_APPROVAL';
  1256|    case 'STATUS_QUERY':
  1257|    case 'DATA_QUERY':
  1258|    case 'BUSINESS_MODULE':
  1259|      return 'ANSWERING';
  1260|    case 'CLARIFICATION':
  1261|      return 'WAITING_FOR_CLARIFICATION';
  1262|    default:
  1263|      return 'THINKING';
