  1267|// ─── Manual Answer Mode Helper (Item 4) ───────────────────────────────
  1268|
  1269|/**
  1270| * Strips manual-answer directives from a message so the clean question
  1271| * can be forwarded to the LLM. This is the fix for the bug where
  1272| * "no tools, explain X" returned "Manual answer mode is active" instead
  1273| * of actually answering the question.
  1274| */
  1275|export function stripManualDirectives(message: string): string {
  1276|  let cleaned = message;
  1277|  for (const pattern of MANUAL_ANSWER_DIRECTIVES) {
  1278|    cleaned = cleaned.replace(pattern, '');
  1279|  }
  1280|  // Clean up leading/trailing punctuation and whitespace left behind
  1281|  cleaned = cleaned.replace(/^[\s,;:.]+/, '').replace(/[\s,;:.]+$/, '').trim();
  1282|  return cleaned || message; // fall back to original if stripping removed everything
  1283|}
