  1287|}
  1288|
  1289|// ─── Canned Response Detector (Item 6) ────────────────────────────────
  1290|
  1291|const CANNED_RESPONSE_INDICATORS: RegExp[] = [
  1292|  /^I am IVX Enterprise Senior Developer mode\b/i,
